{
  "plans": [
    {
      "id": "P36",
      "type": "selection",
      "recordIds": ["F15", "F3"],
      "intent": "Xác định khối lượng băng tối thiểu cần thêm vào để khi trộn với 2 g nước ở 30 °C, hệ thống đạt nhiệt độ cân bằng 5 °C, giả sử không có mất nhiệt ra môi trường.",
      "reasoningSteps": [
        "Tính nhiệt lượng mà 2 g nước giải phóng khi nguội từ 30 °C tới 5 °C bằng Q_water = m·c·ΔT.",
        "Giả sử khối lượng băng thêm là m_ice, nhiệt lượng cần để tan băng và làm ấm nước tan được Q_ice = m_ice·L_f + m_ice·c·ΔT (từ 0 °C tới 5 °C).",
        "Đặt Q_water = Q_ice và giải phương trình để tìm m_ice tối thiểu."
      ]
    },
    {
      "id": "P37",
      "type": "true_false",
      "recordIds": ["F16"],
      "intent": "Kiểm tra tính đúng sai của phát biểu: \"Nếu muốn nhiệt lượng Q₂ mà chất làm lạnh tỏa ra bằng 1500 kJ trong một chu trình có COP = 3, thì công A của máy nén phải ít hơn 300 kJ.\"",
      "reasoningSteps": [
        "Từ quan hệ Q₂ = (COP + 1)·A suy ra A = Q₂ / (COP + 1).",
        "Thay Q₂ = 1500 kJ và COP = 3 để tính A, sau đó so sánh A với 300 kJ để xác định tính đúng sai."
      ]
    },
    {
      "id": "P38",
      "type": "short_answer",
      "recordIds": ["F17"],
      "intent": "Dựa trên tỉ lệ V/T = 0,250 cm³/K, tính nhiệt độ tối thiểu (°C) mà thể tích khí đạt ít nhất 70 cm³, sau đó quyết định xem nhiệt độ này có lớn hơn 25 °C hay không.",
      "reasoningSteps": [
        "Sử dụng công thức V = 0,250·T_K để tìm T_K = V / 0,250 khi V = 70 cm³.",
        "Chuyển đổi T_K sang độ C bằng T_°C = T_K – 273.",
        "So sánh T_°C với 25 °C để đưa ra kết luận."
      ]
    }
  ],
  "evidence": [
    {
      "chunkId": "67e92431-60e9-4666-bb57-78a286b28079",
      "quote": "nóng chảy riêng của nước đá là 3,36.10⁵ J/kg và nhiệt dung riêng của nước là 4200 J/kg.K."
    },
    {
      "chunkId": "e0933adc-ae2f-4a9b-b0ae-1f7bc17f7df3",
      "quote": "Câu 3: Một gia đình đang chuẩn bị bữa ăn ngoài trời vào mùa hè. Họ muốn làm tan và đun nóng 4 kg nước đá từ 0°C để có nước 25°C cho thức uống của mình. Bạn hãy tính xem cần bao nhiêu nhiệt lượng để chuyển nước đá này thành nước ở 25°C. Biết rằng nhiệt nóng chảy riêng của nước đá là 34.10^5 J/kg và nhiệt dung riêng của nước là 4180 J/kg.K?"
    },
    {
      "chunkId": "67e92431-60e9-4666-bb57-78a286b28079",
      "quote": "COP = 3 và A=180kJ trong một chu trình tủ lạnh."
    },
    {
      "chunkId": "3d7f7e69-6fad-4d96-a883-29fac454f4ae",
      "quote": "công thức liên hệ thể tích theo nhiệt độ là V/T = 0,250 trong đó V đo bằng cm³, T đo bằng °K."
    }
  ]
}
